package com.edunest.backend.modules.topic.controller; import com.edunest.backend.common.util.PublicIdUtils; import com.edunest.backend.modules.topic.dto.TopicResponse; import com.edunest.backend.modules.topic.service.TopicService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/topics") @RequiredArgsConstructor public class TopicController { private final TopicService s; @GetMapping("/{id}") public TopicResponse get(@PathVariable String id){return s.getTopicById(PublicIdUtils.parseTopicId(id));} @GetMapping("/unit/{unitId}") public List<TopicResponse> byUnit(@PathVariable String id){return s.getTopicsByUnitId(PublicIdUtils.parseUnitId(id));} }